
--
-- check renaming to a table's array type's autogenerated name
-- (the array type's name should get out of the way)
--
CREATE TABLE atr_arr (id int);
CREATE TABLE atr_arr2 (id int);
SELECT typname FROM pg_type WHERE oid = 'atr_arr[]'::regtype;
SELECT typname FROM pg_type WHERE oid = 'atr_arr2[]'::regtype;
ALTER TABLE atr_arr2 RENAME TO _atr_arr;
SELECT typname FROM pg_type WHERE oid = 'atr_arr[]'::regtype;
SELECT typname FROM pg_type WHERE oid = '_atr_arr[]'::regtype;
DROP TABLE _atr_arr;
DROP TABLE atr_arr;

-- renaming to table's own array type's name is an interesting corner case
CREATE TABLE atr_arr (id int);
SELECT typname FROM pg_type WHERE oid = 'atr_arr[]'::regtype;
ALTER TABLE atr_arr RENAME TO _atr_arr;
SELECT typname FROM pg_type WHERE oid = '_atr_arr[]'::regtype;
create table atr_a (id int);
create table atr_a2 (id int);
alter table atr_a2 rename to _atr_a;
select typname from pg_type where typname like '%atr_a%' order by 1;
select '__atr_a'::regtype, '__atr_a_1'::regtype, '_atr_a'::regtype, '_atr_a[]'::regtype, 'atr_a[]'::regtype;
select pg_typeof(array[row(1)::_atr_a]), pg_typeof(array[row(1)::atr_a]);
create table atr_a3 (a atr_a[], b _atr_a[], c __atr_a);
alter table _atr_a rename to atr_a4;
select typname from pg_type where typname like '%atr_a%' order by 1;
drop table atr_a3, atr_a, atr_a4;
create table atr_b (id int);
create table _atr_b (id int);
select typname from pg_type where typname like '%atr_b%' order by 1;
create type atr_c as (a int);
create type _atr_c as enum ('x');
create domain _atr_c as int;
select typname from pg_type where typname like '%atr_c%' order by 1;
create domain atr_d as int;
create type _atr_d as (a int);
select typname, typtype from pg_type where typname like '%atr_d%' order by 1;
drop table atr_b, _atr_b; drop type atr_c, _atr_c, _atr_d; drop domain atr_d;
